-- Production launch foundation: 20 launch countries + curated city index.
-- Safe/idempotent: existing rows are updated by stable country-code/city identity.

alter table public.countries add column if not exists code text;
alter table public.countries add column if not exists native_name text;
alter table public.cities add column if not exists ascii_name text;
alter table public.cities add column if not exists native_name text;
alter table public.cities add column if not exists population bigint;

update public.cities c set ascii_name='Istanbul', native_name='İstanbul', latitude=41.0082, longitude=28.9784 from public.countries co where c.country_id=co.id and co.code='TR' and lower(c.default_name)=lower('Istanbul');
